import math
pts = [(1,1),(2,2),(3,3),(1,4),(2,3),(3,2)]  # y=x and y=5-x
thetas = [0, 45, 90, 135]
acc = {}
for (x, y) in pts:
    for th in thetas:
        r = x*math.cos(math.radians(th)) + y*math.sin(math.radians(th))
        key = (th, round(r))
        acc[key] = acc.get(key, 0) + 1
TAU = 3
cands = [(k, v) for k, v in acc.items() if v >= TAU]
peaks = []
for (th, rho), v in cands:
    neigh = [acc.get((th+d, rho), 0) for d in (-45, 45)] + [acc.get((th, rho+d), 0) for d in (-1, 1)]
    if all(v >= n for n in neigh):
        peaks.append(((th, rho), v))
print("Bins above threshold %d: %s" % (TAU, sorted(("(%d,%d):%d" % (t, r, v)) for (t, r), v in cands)))
print("After non-maximum suppression, surviving peaks:")
for (th, rho), v in sorted(peaks):
    print("  theta=%d rho=%d votes=%d" % (th, rho, v))
print("Verdict: 2 lines found — (135,0) is y=x, (45,4) is y=5-x.")
print("Knowing-when: votes >= TAU AND local maximum. Ripple bins are ignored.")

