import math, random
rng = random.Random(7)
pts = [(1,1),(2,2),(3,3),(4,4)]
rng.shuffle(pts)
print("Voting order (shuffled):", pts)
TAU = 3
acc = {}
stopped = None
for n, (x, y) in enumerate(pts, 1):
    for th in (0, 45, 90, 135):
        r = x*math.cos(math.radians(th)) + y*math.sin(math.radians(th))
        key = (th, round(r))
        acc[key] = acc.get(key, 0) + 1
    tower = acc.get((135, 0), 0)
    print("  after pixel %d %s: tower(135,0) = %d" % (n, (x, y), tower))
    if tower >= TAU:
        stopped = n
        break
print("Election stopped after %d of %d pixels: tower crossed %d." % (stopped, len(pts), TAU))
print("The shape was made at vote %d. The last vote was never needed." % stopped)
